      role3 = 402206,
      role5 = 4118401,
      sentence = "Redtower has fallen! The chieftain is dead! Vanguard, stand down!",
      voice = 2,
      next = {20}
    },
    [20] = {
      beijing = 2022,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118106,
      role3 = 402206,
      role5 = 4118401,
      sentence = "He stabbed the black flag into the center of the wall, holding his head high under the light of day with a wrathful eye.",
      next = {21}
    },
    [21] = {
      beijing = 2022,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "The fluttering flag stood as firmly as a monolith against the blustering wind, and the menacing drums of Sparrovia began to beat. The sound was like a mournful sob, or like the trembling of tears welling up in one's eyes.",
      next = {22}
    },
    [22] = {
      beijing = 2022,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "All there had waited for this moment for too long.",
      next = {23}
    },
    [23] = {
