      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Fifty thousand souls could now rest in peace.",
