    },
    [25] = {
      beijing = 2022,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402202,
      role5 = 4118401,
      sentence = "As I watched that figure on the wall, a hot rush of blood surged through my heart. Gavin seemed to spot me too, and his brow raised slightly.",
      next = {26}
    },
    [26] = {
      beijing = 2022,
      dialog = 3,
