      role1 = 4118000,
      role2 = 4118108,
      role3 = 402202,
      role5 = 4118401,
      ruchang = 9,
      sentence = "The fires of war obviously still burned behind him, but he was as proud and undaunted as if he'd just conquered the world.",
      next = {27}
    },
    [27] = {
      beijing = 2255,
      bganim = 0,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "After making it into the city, I immediately went to the command tent of the garrison.",
      next = {28}
    },
    [28] = {
      beijing = 2255,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "Inside the tent, it seemed like a meeting had just finished. There was no one else in the tent, not even a low-ranked soldier. When I pushed my way in, the first thing I saw was Gavin.",
      next = {29}
    },
    [29] = {
      beijing = 64061,
      bganim = 0,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "When he looked up and saw it was me, he put down the battle report in his hand and let out a laugh.",
      next = {30}
    },
    [30] = {
      beijing = 64061,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "28_Double_Seventh02",
      renming = "Gavin",
      renwu = "npc",
      sentence = "You saw your first real battle today. Were you scared?",
