      next = {31}
    },
    [31] = {
      beijing = 64061,
      dhead = 1506,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "I was, but not scared of the battle, but that Your Highness would be injured by some stray blade.",
