    },
    [32] = {
      beijing = 64061,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "He froze for a moment and wanted to say something, but I made a quick salute and then stepped forward to grab his wrist guard.",
      next = {33}
    },
    [33] = {
      beijing = 64061,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "I bumped against his cloak collar, hesitated a moment, and then decided to undo it and examine him for wounds.",
      next = {34}
    },
    [34] = {
      beijing = 64061,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "Up there on the wall just now, although he seemed steady and strong, I still spotted a red stain on his collar.",
      next = {35}
    },
    [35] = {
      beijing = 64061,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "But Gavin took hold of my hand and stopped me.",
