      dialog = 2,
      idx = 4,
      male = 4,
      music = "28_Double_Seventh02",
      renming = "Gavin",
      renwu = "npc",
      sentence = "The enemy's provisions were heavily guarded. For this sneak attack to succeed, there was a price to be paid.",
      voice = 2,
      next = {40}
    },
    [40] = {
      beijing = 64061,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "Two years of worry came to a head in this moment, leaving me trembling. I looked down and gripped his collar, then heard a laugh escape from Gavin's throat.",
      next = {41}
    },
    [41] = {
      beijing = 2255,
