      idx = 4,
      male = 4,
      music = "28_Double_Seventh02",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4117000,
      role2 = 4117111,
      role3 = 403207,
      role5 = 4117401,
      ruchang = -1,
      sentence = "Inspector, every time you've seen me, it's been like a mouse seeing a cat.",
      voice = 2,
