      role2 = 4117106,
      role3 = 403203,
      role5 = 4117401,
      roleanim = 1.1,
      sentence = "I answered with a shaky voice. Gavin fell silent, then suddenly went limp and leaned on my shoulder, his crown brushing against the skin of my neck.",
