      renwu = "npc",
      role1 = 4117000,
      role2 = 4117106,
      role3 = 403203,
      role5 = 4117401,
      roleanim = 1.1,
      sentence = "I won't put up a front anymore. I haven't slept in over a day, and my old wound was hit by an arrow. I'm both injured and tired.",
