      role3 = 403203,
      role5 = 4117401,
      roleanim = 1.1,
      ruchang = 9,
      sentence = "A moment later, his breathing steadied out. He really had fallen asleep. I was completely hand-tied, and all I could do was do my best to be his pillow.",
