    [53] = {
      beijing = 2255,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "Even with the commotion from Eli, Gavin still didn't wake. As I listened to his breathing, my thoughts began to wander, and I couldn't help but think of that promise.",
