    },
    [55] = {
      beijing = 2255,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "As I was worrying about how I would extricate myself from this business, he seemed to present me with an opportunity all wrapped up in a bow.",
      next = {56}
    },
    [56] = {
      beijing = 2255,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "An opportunity where I would both get to keep my promise and avoid letting him in on what was in my heart of hearts.",
