      beijing = 2255,
      dhead = 1508,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "In that battle, you were surrounded for ten days and ten nights. Back in the capital, I kept waiting and waiting for the court to send troops, and cursing my own helplessness.",
      next = {60}
    },
    [60] = {
      beijing = 2255,
      dhead = 1508,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "So I decided to join, to protect you from within the court.",
