      role1 = 4117000,
      role2 = 4117111,
      role3 = 403207,
      role5 = 4117401,
      roleanim = 1.1,
      ruchang = -1,
      sentence = "As I confessed my thoughts in a low voice, an unmistakable muffled laugh hit my ear. I turned my head in shock to see Gavin's shining eyes.",
